import { Component } from "@angular/core";
import { FormBuilder, FormGroup, Validators } from "@angular/forms";
import { Router } from "@angular/router";
import { AuthService } from "../../services/auth.service";

@Component({
  selector: "app-register",
  templateUrl: "./register.component.html",
  styleUrls: ["./register.component.css"],
})
export class RegisterComponent {
  registerForm: FormGroup;
  loading = false;

  constructor(
    private fb: FormBuilder,
    private auth: AuthService,
    private router: Router,
  ) {
    this.registerForm = this.fb.group({
      name: ["", Validators.required],
      email: ["", [Validators.required, Validators.email]],
      password: ["", [Validators.required, Validators.minLength(6)]],
    });
  }

  onSubmit(): void {
    if (this.registerForm.invalid) {
      this.registerForm.markAllAsTouched();
      return;
    }
    this.loading = true;
    this.auth
      .register(this.registerForm.value)
      .subscribe(() => this.router.navigate(["/"]));
  }
}
<div class="auth-page">
  <div class="auth-card">
    <div class="auth-brand">🛍️ ShopEZ</div>
    <h2>Create Account</h2>
    <p class="auth-sub">Join us and start shopping!</p>

    <form [formGroup]="registerForm" (ngSubmit)="onSubmit()">
      <div class="form-group">
        <label>Full Name</label>
        <input type="text" formControlName="name" placeholder="John Doe" />
        <span
          class="err"
          *ngIf="
            registerForm.get('name')?.invalid &&
            registerForm.get('name')?.touched
          "
          >Name is required.</span
        >
      </div>
      <div class="form-group">
        <label>Email</label>
        <input
          type="email"
          formControlName="email"
          placeholder="ram@email.com"
        />
        <span
          class="err"
          *ngIf="
            registerForm.get('email')?.invalid &&
            registerForm.get('email')?.touched
          "
          >Valid email required.</span
        >
      </div>
      <div class="form-group">
        <label>Password</label>
        <input
          type="password"
          formControlName="password"
          placeholder="Min 6 characters"
        />
        <span
          class="err"
          *ngIf="
            registerForm.get('password')?.invalid &&
            registerForm.get('password')?.touched
          "
          >Min 6 characters required.</span
        >
      </div>
      <button type="submit" class="auth-btn" [disabled]="loading">
        {{ loading ? "Creating account..." : "Create Account" }}
      </button>
    </form>

    <p class="auth-link">
      Already have an account? <a routerLink="/login">Sign In</a>
    </p>
  </div>
</div>
